<?php
/**
 * Assets Management
 *
 * @package Gravisain\Core
 */

namespace Gravisain\Core;

/**
 * Assets Class
 * 
 * Handles the conditional enqueuing of CSS and JavaScript files
 * generated by Vite.
 */
class Assets {

	/**
	 * Initialize the Assets service.
	 *
	 * @return void
	 */
	public static function init(): void {
		$instance = new self();
		$instance->setup_hooks();
	}

	/**
	 * Setup hooks for assets.
	 *
	 * @return void
	 */
	private function setup_hooks(): void {
		add_action( 'wp_head', [ $this, 'print_theme_anti_flicker_script' ], 0 );
		add_action( 'wp_enqueue_scripts', [ $this, 'enqueue_frontend_assets' ] );
		add_action( 'admin_enqueue_scripts', [ $this, 'enqueue_admin_assets' ] );
		add_action( 'enqueue_block_editor_assets', [ $this, 'enqueue_editor_assets' ] );
		add_action( 'admin_head', [ $this, 'print_admin_antiflicker_styles' ] );
	}

	/**
	 * Enqueue frontend CSS and JS.
	 *
	 * @return void
	 */
	public function enqueue_frontend_assets(): void {
		$theme_version = wp_get_theme()->get( 'Version' );
		$theme_uri     = get_template_directory_uri();

		// Main Stylesheet (style.css fallback).
		wp_enqueue_style(
			'gravisain-style',
			get_stylesheet_uri(),
			[],
			$theme_version
		);

		// Load Vite Assets from manifest
		$manifest_path = file_exists( get_template_directory() . '/assets/manifest.json' )
			? get_template_directory() . '/assets/manifest.json'
			: get_template_directory() . '/assets/.vite/manifest.json';
		if ( file_exists( $manifest_path ) ) {
			$manifest      = json_decode( file_get_contents( $manifest_path ), true );
			$asset_version = $theme_version . '.' . filemtime( $manifest_path );

			// CSS
			if ( isset( $manifest['src/css/main.css']['file'] ) ) {
				wp_enqueue_style(
					'gravisain-vite-css',
					get_template_directory_uri() . '/assets/' . $manifest['src/css/main.css']['file'],
					[],
					$asset_version
				);
			}

			// JS
			if ( isset( $manifest['src/js/main.js']['file'] ) ) {
				wp_enqueue_script(
					'gravisain-vite-js',
					get_template_directory_uri() . '/assets/' . $manifest['src/js/main.js']['file'],
					[],
					$asset_version,
					true
				);
			}
		}

		if ( is_singular() && comments_open() && get_option( 'thread_comments' ) ) {
			wp_enqueue_script( 'comment-reply' );
		}
	}

	/**
	 * Enqueue admin CSS and JS.
	 *
	 * @return void
	 */
	public function enqueue_admin_assets(): void {
		// Admin assets can be enqueued here if needed.
	}

	/**
	 * Enqueue Block Editor Assets (ensure crisp white canvas background).
	 *
	 * @return void
	 */
	public function enqueue_editor_assets(): void {
		$theme_version = wp_get_theme()->get( 'Version' );
		$manifest_path = file_exists( get_template_directory() . '/assets/manifest.json' )
			? get_template_directory() . '/assets/manifest.json'
			: get_template_directory() . '/assets/.vite/manifest.json';
		if ( file_exists( $manifest_path ) ) {
			$manifest      = json_decode( file_get_contents( $manifest_path ), true );
			$asset_version = $theme_version . '.' . filemtime( $manifest_path );
			if ( isset( $manifest['src/css/main.css']['file'] ) ) {
				wp_enqueue_style(
					'gravisain-vite-editor-css',
					get_template_directory_uri() . '/assets/' . $manifest['src/css/main.css']['file'],
					[],
					$asset_version
				);
			}
		}

		$custom_css = '
			.editor-styles-wrapper,
			.editor-styles-wrapper .is-root-container,
			.editor-styles-wrapper .wp-site-blocks,
			.editor-styles-wrapper .edit-post-visual-editor__post-title-wrapper {
				background-color: #ffffff !important;
				color: #0f172a;
			}
		';
		wp_register_style( 'gravisain-editor-canvas', false );
		wp_enqueue_style( 'gravisain-editor-canvas' );
		wp_add_inline_style( 'gravisain-editor-canvas', $custom_css );
	}

	/**
	 * Print inline style directly in admin head to prevent any layout shifts/flicker.
	 *
	 * @return void
	 */
	public function print_admin_antiflicker_styles(): void {
		?>
		<style id="gravisain-admin-antiflicker">
			/* Prevent layout shift & blinking of metaboxes below the canvas during device switch */
			.edit-post-layout__metaboxes {
				clear: both !important;
			}
			/* Hide metaboxes area completely when previewing mobile or tablet devices to eliminate blinking/layout shifts */
			.is-previewing-tablet .edit-post-layout__metaboxes,
			.is-previewing-mobile .edit-post-layout__metaboxes,
			.is-previewing-device .edit-post-layout__metaboxes,
			body:not(.is-previewing-desktop) .edit-post-layout__metaboxes,
			.edit-post-layout:not(.is-previewing-desktop) .edit-post-layout__metaboxes,
			.edit-post-layout__metaboxes:empty,
			.edit-post-layout__metaboxes:not(:has(.postbox)) {
				display: none !important;
				visibility: hidden !important;
				height: 0 !important;
				overflow: hidden !important;
			}
		</style>
		<?php
	}

	/**
	 * Print inline script directly in head to prevent FOUC / light-dark blinking.
	 *
	 * @return void
	 */
	public function print_theme_anti_flicker_script(): void {
		$default_mode = get_theme_mod( 'gravisain_header_theme_switcher_default', 'system' );
		?>
		<script id="gravisain-theme-mode-init">
			(function() {
				try {
					var fallback = <?php echo wp_json_encode( $default_mode ); ?> || 'system';
					var storedTheme = localStorage.getItem('gravisain_theme') || fallback;
					var isDark = storedTheme === 'dark' || (storedTheme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
					if (isDark) {
						document.documentElement.classList.add('dark');
						document.documentElement.setAttribute('data-theme', 'dark');
					} else {
						document.documentElement.classList.remove('dark');
						document.documentElement.setAttribute('data-theme', 'light');
					}
				} catch (e) {}
			})();
		</script>
		<?php
	}
}

